CREATE TABLE IF NOT EXISTS incident_assessments (incident_id TEXT PRIMARY KEY NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), ratings TEXT NOT NULL CHECK(json_valid(ratings)), confidence TEXT NOT NULL CHECK(confidence IN ('A','B','C','D')), source_urls TEXT NOT NULL CHECK(json_valid(source_urls)), rationale TEXT NOT NULL, reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incident_assessment_history (id INTEGER PRIMARY KEY AUTOINCREMENT, incident_id TEXT NOT NULL, score INTEGER NOT NULL, ratings TEXT NOT NULL, confidence TEXT NOT NULL, source_urls TEXT NOT NULL, rationale TEXT NOT NULL, reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_incident_assessment_history_incident ON incident_assessment_history(incident_id,reviewed_at);
